// === Tab: background ===
function noiseBlob(graphic, x, y, r0, delta, noiseStrength, resolution) {
    let r, theta;
    graphic.beginShape();
    for (let i = 0; i < 360; i += (Math.max(0.001, Math.abs(resolution)) || 1)) {
      theta = radians(i);
      r = r0 * (1 + noiseStrength*noise(delta+cos(theta), delta+sin(theta)));
      graphic.vertex(x + r*cos(theta), y + r*sin(theta));
    }
    graphic.endShape(CLOSE);
  }

  function createBackground() {
    let delta = 0.2;
    bg.background(255,245,240);
    fill(250, 0, 0);
    bg.fill(230, 200, 150);
    noiseBlob(
      bg,
      width/2 + height*random(-delta, delta),
      height/2 + height*random(-delta, delta),
      height/7,
      random(TWO_PI),
      1,
      1
    );
    bg.fill(232, 142, 97);
    noiseBlob(
      bg,
      width/2 + height*random(-delta, delta),
      height/2 + height*random(-delta, delta),
      height/9,
      random(TWO_PI),
      1,
      1);
  }

// === Tab: branch ===
function createBranch() {
    let maxAngle = map(width/height, 0.5, 2, 15, 45);
    let angle = random(-maxAngle, maxAngle);
    let position = {x: width/2, y: 3*height/4, angle: radians(angle)};
    let length = height/2;
    let branchSteps = random(5, 12);

    let branchPoints = [
        {x: random(1, 1)*length, y: length},
        {x: 0, y: 0},
        {x: 0, y: -length},
        {x: random(-1, 1)*length, y: -2*length}
    ];

    let baseLeafConfig = {};
    baseLeafConfig.size = { w: length/branchSteps, h: random(300, 500)*0.001*length };
    baseLeafConfig.opening = { base: radians(random(30)), apex: radians(random(30)), margin: radians(random(-15, 15)) };
    baseLeafConfig.modLength = { base: random(0.2), apex: random(0.2), baseMargin: random(0.2, 0.3), apexMargin: random(0.2, 0.4) };
    baseLeafConfig.distortion = { dMargin: random(0.3, 0.5), leafAngle: radians(random(-15)) };

    let axilConfig = {orientation: radians(random(15,30)), size: random(15, 30)*0.001*length};
    // leafs will be draw on random order
    let leafs = orderLeafs(branchSteps);

    drawBranch(position, branchPoints, branchSteps, baseLeafConfig, axilConfig, leafs);
}

function drawBranch(position, branchPoints, steps, baseLeafConfig, axilConfig, leafs) {
    pushGraphics([main, debug], position);

    // first half of leafs behind branch
    for (let idx = 0; idx < floor(leafs.length/2); idx++) {
        createBranchLeaf(branchPoints, leafs[idx].i, steps, leafs[idx].direction, baseLeafConfig, axilConfig);
    }

    drawBranchCurve(main, false, branchPoints);
    drawBranchCurve(debug, true, branchPoints);

     // second half of leafs in front of branch
    for (let idx = floor(leafs.length/2); idx < leafs.length; idx++) {
        createBranchLeaf(branchPoints, leafs[idx].i, steps, leafs[idx].direction, baseLeafConfig, axilConfig);
    }

    popGraphics([main, debug]);
}

function pushGraphics(graphics, position) {
    for (const graphic of graphics) {
        graphic.push();
        graphic.translate(position.x, position.y);
        graphic.rotate(position.angle);
    }
}

function popGraphics(graphics) {
    for (const graphic of graphics) {
        graphic.pop();
    }
}

function getCurvePoint(curvePoints, i) {
    let x = curvePoint(curvePoints[0].x, curvePoints[1].x, curvePoints[2].x, curvePoints[3].x, i);
    let y = curvePoint(curvePoints[0].y, curvePoints[1].y, curvePoints[2].y, curvePoints[3].y, i);
    return createVector(x, y);
}

function createBranchLeaf(curvePoints, i, steps, direction, baseLeafConfig, axilConfig) {
    let dSize = -1.095*i*i+0.995*i+0.8;
    let currLeafSize = {
        w: baseLeafConfig.size.w * dSize * random(0.85, 1.15),
        h: baseLeafConfig.size.h * dSize * random(0.85, 1.15)
    };
    let currLeafDistortion = {
        dMargin: baseLeafConfig.distortion.dMargin + random(-0.05, 0.05),
        leafAngle: direction*(baseLeafConfig.distortion.leafAngle + radians(random(15)))
    };

    let pos = getCurvePoint(curvePoints, i);
    let ppos = getCurvePoint(curvePoints, i + 1/steps);
    let currAngle = p5.Vector.sub(ppos, pos).heading();

    var angle = currAngle - direction*(-HALF_PI + axilConfig.orientation + lerp(0, axilConfig.orientation, i) + radians(random(-15, 15)));
    let leafPos = { x: pos.x + axilConfig.size*cos(angle), y: pos.y + axilConfig.size*sin(angle), theta: angle };

    createAxil(pos, leafPos);
    createLeaf(leafPos, currLeafSize, baseLeafConfig.opening, baseLeafConfig.modLength, currLeafDistortion, 1 /*leafSteps*/);
}

function orderLeafs(steps) {
    var leafs = [];
    // leaf of the tip
    leafs.push({i: 1, direction:0});

    for (let i = 1; i > 0; i -= 1/steps) {
        // other leafs on pairs
        leafs.push({i:i, direction:-1});
        leafs.push({i:i, direction:1});
    }
    return shuffle(leafs);
}

function drawBranchCurve(graphic, isDebug, branchPoints) {
    if (isDebug) {
        graphic.noFill();
        graphic.curve(
            branchPoints[0].x, branchPoints[0].y,
            branchPoints[0].x, branchPoints[0].y,
            branchPoints[1].x, branchPoints[1].y,
            branchPoints[2].x, branchPoints[2].y
        );
        graphic.curve(
            branchPoints[0].x, branchPoints[0].y,
            branchPoints[1].x, branchPoints[1].y,
            branchPoints[2].x, branchPoints[2].y,
            branchPoints[3].x, branchPoints[3].y
        );
        graphic.curve(
            branchPoints[1].x, branchPoints[1].y,
            branchPoints[2].x, branchPoints[2].y,
            branchPoints[3].x, branchPoints[3].y,
            branchPoints[3].x, branchPoints[3].y
        );
        let diam = 0.01*height;
        graphic.circle(branchPoints[0].x, branchPoints[0].y, diam);
        graphic.circle(branchPoints[1].x, branchPoints[1].y, diam);
        graphic.circle(branchPoints[2].x, branchPoints[2].y, diam);
        graphic.circle(branchPoints[3].x, branchPoints[3].y, diam);

    } else {
        graphic.stroke(hue, saturation, brightness);

        graphic.beginShape();
        var ppos = getCurvePoint(branchPoints, 1);
        let step = 0.01
        for (let i = 1-step; i >= -5*step; i -= step) {
            graphic.strokeWeight(lerp(0.002, 0.001, i*i)*height);
            var pos = getCurvePoint(branchPoints, i);
            graphic.line(ppos.x, ppos.y, pos.x, pos.y);
            ppos = pos;
        }
        graphic.endShape();
    }
}

function createAxil(begin, end) {
    drawAxil(main, false, begin, end);
    drawAxil(debug, true, begin, end);
}

function drawAxil(graphic, isDebug, begin, end) {
    if (!isDebug) {
        graphic.stroke(hue, saturation, brightness);
        graphic.strokeWeight(0.001*height);
    }
    graphic.line(begin.x, begin.y, end.x, end.y);
}

// === Tab: leaf ===
function createLeaf(pos, size, opening, modLength, distortion, steps) {
    let baseMMag = modLength.base * size.h;
    let base = {};
    base.p = createVector(0, 0);
    base.m = {};
    base.m.right = constructVector(distortion.leafAngle + opening.base, baseMMag, base.p);
    base.m.left = constructVector(distortion.leafAngle - opening.base, baseMMag, base.p);
    base.m.center = constructVector(distortion.leafAngle, baseMMag, base.p);

    let apexMMag = modLength.apex * size.h;
    let apex = {};
    apex.p = createVector(size.h, 0);
    apex.m = {};
    apex.m.left = constructVector(PI - distortion.leafAngle + opening.apex, apexMMag, apex.p);
    apex.m.right = constructVector(PI - distortion.leafAngle - opening.apex, apexMMag, apex.p);
    apex.m.center = constructVector(PI - distortion.leafAngle, apexMMag, apex.p);

    let baseMarginMag = modLength.baseMargin * size.h;
    let apexMarginMag = modLength.apexMargin * size.h;
    let marginPos = distortion.dMargin * size.h;
    let marginW = 0.5 * size.w;
    let dAngleW = size.w * sin(distortion.leafAngle);
    let margin = {};
    margin.left = {};
    margin.left.p = createVector(marginPos, -marginW + dAngleW);
    margin.left.m = {};
    margin.left.m.before = constructVector(PI + distortion.leafAngle - opening.margin, baseMarginMag, margin.left.p);
    margin.left.m.after = constructVector(distortion.leafAngle - opening.margin, apexMarginMag, margin.left.p);
    margin.right = {};
    margin.right.p = createVector(marginPos, marginW + dAngleW);
    margin.right.m = {};
    margin.right.m.before = constructVector(distortion.leafAngle + opening.margin, apexMarginMag, margin.right.p);
    margin.right.m.after = constructVector(PI + distortion.leafAngle + opening.margin, baseMarginMag, margin.right.p);

    let midrib = {};
    midrib.p = createVector(marginPos, dAngleW);
    midrib.m = {};
    midrib.m.before = p5.Vector.fromAngle(PI + distortion.leafAngle).setMag(apexMarginMag).add(midrib.p);
    midrib.m.after = p5.Vector.fromAngle(distortion.leafAngle).setMag(baseMarginMag).add(midrib.p);

    for (let i = 1; i >= 0; i -= 1/steps) {
      drawLeaf(main, false, pos, base, margin, midrib, apex, i);
      drawLeaf(debug, true, pos, base, margin, midrib, apex, i);
    }
  }

  function drawLeaf(graphic, isDebug, pos, base, margin, midrib, apex, i) {
    graphic.push();
    graphic.translate(pos.x, pos.y);
    graphic.rotate(pos.theta);

    graphic.beginShape();
    bezierStep(
      base.p,
      p5.Vector.lerp(base.m.center, base.m.left, i),
      p5.Vector.lerp(midrib.m.before, margin.left.m.before, i),
      p5.Vector.lerp(midrib.p, margin.left.p, i),
      true /*isBeginning*/,
      graphic,
      isDebug,
    ); 
    bezierStep(
      p5.Vector.lerp(midrib.p, margin.left.p, i),
      p5.Vector.lerp(midrib.m.after, margin.left.m.after, i),
      p5.Vector.lerp(apex.m.center, apex.m.left, i),
      apex.p,
      false /*isBeginning*/,
      graphic,
      isDebug
    );
    bezierStep(
      apex.p,
      p5.Vector.lerp(apex.m.center, apex.m.right, i),
      p5.Vector.lerp(midrib.m.after, margin.right.m.before, i),
      p5.Vector.lerp(midrib.p, margin.right.p, i),
      false /*isBeginning*/,
      graphic,
      isDebug
    );
    bezierStep(
      p5.Vector.lerp(midrib.p, margin.right.p, i),
      p5.Vector.lerp(midrib.m.before, margin.right.m.after, i),
      p5.Vector.lerp(base.m.center, base.m.right, i),
      base.p,
      false /*isBeginning*/,
      graphic,
      isDebug
    ); 
    graphic.endShape();

    graphic.pop();
  }

  function bezierStep(a, b, c, d, isBeginning, graphic, isDebug) {
    if (!isDebug) {
      graphic.strokeWeight(0.001*height);
      graphic.stroke(hue, saturation, brightness);
      graphic.fill(hue, saturation, random(50, 60));
    }

    if (isBeginning) {
      graphic.vertex(a.x, a.y);
    }
    graphic.bezierVertex(b.x, b.y, c.x, c.y, d.x, d.y);

    if (isDebug) {  
      graphic.line(a.x, a.y, b.x, b.y);
      graphic.line(c.x, c.y, d.x, d.y);

      var diam = 0.01*height;
      graphic.circle(a.x, a.y, diam);
      graphic.circle(b.x, b.y, diam);  
      graphic.circle(c.x, c.y, diam);
      graphic.circle(d.x, d.y, diam);
    }
  }

  function constructVector(angle, magnitude, dislocation) {
    return p5.Vector.fromAngle(angle).setMag(magnitude).add(dislocation);
  }

