let main, debug, bg;
let hue = 100, saturation = 30, brightness = 35;
let showDebug = false;

function setup() {
  createCanvas(windowWidth, windowHeight);

  main = createGraphics(width, height);
  main.colorMode(HSB, 360, 100, 100, 100);

  debug = createGraphics(width, height);
  debug.noFill();
  debug.strokeWeight(0.002*height);
  debug.stroke(20,0,60);

  bg = createGraphics(width, height);
  bg.noStroke();
  noiseDetail(2, 0.2);

  createDrawing();
}

function draw() {
  image(bg, 0, 0);
  image(main, 0, 0);
  if (showDebug) {
    image(debug, 0, 0);
  }
}

function mousePressed() {
  createDrawing(main, debug);
}

function keyPressed() {
  showDebug = !showDebug;
}

function createDrawing() {
  debug.clear();
  debug.background(255, 127);

  main.clear();

  createBackground();
  createBranch();
}
